const b = $json.body || {};
// Authentication is the Webhook node's Header Auth (X-Conveyor-Token = fr's CONVEYOR_START_WEBHOOK_SECRET).
if (b.source !== 'operator') throw new Error('kata.open: body.source must be "operator"');
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const project = String(b.source_project_id || '').trim();
if (!UUID.test(project)) throw new Error('kata.open: source_project_id must be a uuid');
const card = String(b.source_card_id || '').trim();
if (!/^[0-9]{1,30}$/.test(card)) throw new Error('kata.open: source_card_id must be a Planka card id');
const symptom = String(b.symptom || '').trim();
if (!symptom) throw new Error('kata.open: symptom is required');
const exec = String(b.source_execution_id || '').trim();
if (exec && !/^[0-9]{1,20}$/.test(exec)) throw new Error('kata.open: source_execution_id must be an n8n execution id');
const by = String(b.requested_by || '').trim();
if (by && !UUID.test(by)) throw new Error('kata.open: requested_by must be a uuid');
return [{ json: { source_project_id: project.toLowerCase(), source_card_id: card, source_execution_id: exec, symptom: symptom.slice(0, 2048), requested_by: by.toLowerCase() } }];

const inp = $('Input').first().json;
const r = $json;
if (r.error !== undefined && r.operation !== undefined) throw new Error('Card ' + inp.source_card_id + ': ' + String(typeof r.error === 'string' ? r.error : JSON.stringify(r.error)).slice(0, 500));
const card = r.item || r;
if (!card || String(card.id) !== inp.source_card_id) throw new Error('Card: no card ' + inp.source_card_id + ' in the response');
return [{ json: { card_id: String(card.id), board_id: String(card.boardId), list_id: String(card.listId) } }];

const inp = $('Input').first().json;
const c = $('Check Card').first().json;
const r = $json;
if (r.error !== undefined && r.operation !== undefined) throw new Error('Board ' + c.board_id + ': ' + String(typeof r.error === 'string' ? r.error : JSON.stringify(r.error)).slice(0, 500));
const lists = (r.included && r.included.lists) || r.lists || [];
const l = (Array.isArray(lists) ? lists : []).find(function (x) { return String(x.id) === c.list_id; });
if (!l) throw new Error('card ' + c.card_id + ': list ' + c.list_id + ' is not on board ' + c.board_id);
return [{ json: Object.assign({}, inp, { board_id: c.board_id, phase: String(l.name || '').trim().toUpperCase() }) }];

// Prefer a previous coach run for this card: its Start input holds the exact coach inputs, so the
// signature (flow | node | check) matches the automatic one and fr's dedup / rollback work.
const c = $('Card list').first().json;
let execs = [];
$input.all().forEach(function (i) {
  const j = i.json || {};
  if (Array.isArray(j.data)) execs = execs.concat(j.data);
  else if (j.id !== undefined && j.data && j.data.resultData) execs.push(j);
});
const hits = [];
execs.forEach(function (e) {
  let s = null;
  try { s = e.data.resultData.runData.Start[0].data.main[0][0].json; } catch (x) { s = null; }
  if (!s || String(s.card_id) !== c.source_card_id) return;
  if (c.source_execution_id && String(s.execution_id) !== c.source_execution_id) return;
  hits.push({ at: String(e.startedAt || ''), s: s });
});
hits.sort(function (a, b) { return a.at < b.at ? 1 : (a.at > b.at ? -1 : 0); });
if (hits.length) {
  const s = hits[0].s;
  const keys = ['card_id', 'board_id', 'list', 'card_type', 'flow_name', 'flow_id', 'execution_id', 'phase', 'node', 'check'];
  const inputs = {};
  keys.forEach(function (k) { inputs[k] = (s[k] === undefined || s[k] === null) ? '' : String(s[k]); });
  inputs.block_text = ('Operator: ' + c.symptom + (s.block_text ? '\n\n' + String(s.block_text) : '')).slice(0, 4000);
  return [{ json: { need_exec: false, source: 'coach run', inputs: inputs } }];
}
if (!c.source_execution_id) throw new Error('no coach run found for card ' + c.source_card_id + ' and no source_execution_id; pass the failing execution id');
return [{ json: { need_exec: true } }];

const c = $('Card list').first().json;
const r = $json;
if (r.error !== undefined && r.operation !== undefined) throw new Error('Get execution ' + c.source_execution_id + ': ' + String(typeof r.error === 'string' ? r.error : JSON.stringify(r.error)).slice(0, 500));
const e = (r.data && r.data.resultData) ? r : (r.execution || r);
const rd = (e.data && e.data.resultData) || {};
const wd = e.workflowData || {};
const flow_name = String(wd.name || '');
if (!flow_name) throw new Error('execution ' + c.source_execution_id + ' carries no workflow name');
const dot = flow_name.lastIndexOf('.');
const errMsg = String((rd.error && (rd.error.message || rd.error.description)) || '');
const inputs = { card_id: c.source_card_id, board_id: c.board_id, list: c.phase, card_type: dot > 0 ? flow_name.slice(0, dot) : flow_name,
  flow_name: flow_name, flow_id: String(e.workflowId || wd.id || ''), execution_id: c.source_execution_id, phase: c.phase,
  node: String(rd.lastNodeExecuted || ''), check: 'operator',
  block_text: ('Operator: ' + c.symptom + (errMsg ? '\n\n' + errMsg : '')).slice(0, 4000) };
if (!inputs.flow_id || !inputs.node) throw new Error('execution ' + c.source_execution_id + ' lacks ' + (!inputs.flow_id ? 'workflowId' : 'lastNodeExecuted'));
return [{ json: { need_exec: false, source: 'execution', inputs: inputs } }];

const e = $json.error;
let msg = (typeof e === 'string') ? e : ((e && (e.message || e.description)) || $json.message || JSON.stringify($json).slice(0, 500));
let prev = '';
try { prev = $prevNode.name; } catch (x) { prev = ''; }
let card = '';
try { card = $('Input').first().json.source_card_id; } catch (x) { card = ''; }
if (!card) { try { card = String((($('Webhook').first().json.body) || {}).source_card_id || ''); } catch (x) { card = ''; } }
return [{ json: { reason: 'kata.open failed' + (prev ? ' at ' + prev : '') + ': ' + String(msg).slice(0, 1500), card_id: /^[0-9]{1,30}$/.test(card) ? card : '' } }];
